from functools import lru_cache

def count_distinct_digit_numbers(n):
    s = str(n)
    @lru_cache(None)
    def go(i, mask, tight, started):
        if i == len(s):
            return 1 if started else 0
        hi = int(s[i]) if tight else 9
        tot = 0
        for d in range(hi + 1):
            if started and mask >> d & 1:
                continue
            if not started and d == 0:
                tot += go(i + 1, mask, tight and d == hi, False)
            else:
                tot += go(i + 1, mask | 1 << d, tight and d == hi, True)
        return tot
    return go(0, 0, True, False)

